code.cpp:
class Solution {
public:
    bool increasingTriplet(vector<int>& nums) {
        long long first = 1LL << 60;
        long long second = 1LL << 60;
        for (int x : nums) {
            if (x <= first) {
                first = x;
            } else if (x <= second) {
                second = x;
            } else {
                return true;
            }
        }
        return false;
    }
};
